#!/usr/bin/env python3
"""Dependency-free command-line analytics for CSV files."""

from __future__ import annotations

import argparse
import csv
import json
import sys
from collections import OrderedDict
from decimal import Decimal, InvalidOperation
from pathlib import Path
from typing import NoReturn, Sequence, TextIO


class CsvInsightsError(Exception):
    """An input or command-line validation error."""


def fail(message: str) -> NoReturn:
    print(f"error: {message}", file=sys.stderr)
    raise SystemExit(1)


def parse_args(argv: Sequence[str] | None = None) -> argparse.Namespace:
    parser = argparse.ArgumentParser(
        description="Filter and aggregate an RFC-style CSV file."
    )
    parser.add_argument("input", metavar="INPUT.csv", help="CSV file to read")
    parser.add_argument(
        "--where",
        action="append",
        default=[],
        metavar="COLUMN=VALUE",
        help="keep rows whose column exactly equals value (repeatable)",
    )
    parser.add_argument("--group-by", metavar="COLUMN")
    parser.add_argument(
        "--sum", dest="sum_columns", action="append", default=[], metavar="COLUMN"
    )
    parser.add_argument(
        "--avg", dest="avg_columns", action="append", default=[], metavar="COLUMN"
    )
    parser.add_argument("--output", choices=("json", "csv"), default="json")
    args = parser.parse_args(argv)

    if (args.sum_columns or args.avg_columns) and not args.group_by:
        parser.error("--sum and --avg require --group-by")
    if args.group_by and not (args.sum_columns or args.avg_columns):
        parser.error("--group-by requires --sum and/or --avg")
    return args


def read_csv(path: str) -> tuple[list[str], list[tuple[int, list[str]]]]:
    try:
        with Path(path).open("r", encoding="utf-8", newline="") as source:
            reader = csv.reader(source, strict=True)
            try:
                header = next(reader)
            except StopIteration:
                raise CsvInsightsError("input is empty") from None

            if not header:
                raise CsvInsightsError("header row is empty")
            empty_positions = [str(i + 1) for i, name in enumerate(header) if not name]
            if empty_positions:
                raise CsvInsightsError(
                    "header names must be non-empty "
                    f"(empty field at column {', '.join(empty_positions)})"
                )
            duplicates = sorted({name for name in header if header.count(name) > 1})
            if duplicates:
                raise CsvInsightsError(
                    "header names must be unique "
                    f"(duplicate: {', '.join(repr(name) for name in duplicates)})"
                )

            rows: list[tuple[int, list[str]]] = []
            for record_number, row in enumerate(reader, start=2):
                if len(row) != len(header):
                    raise CsvInsightsError(
                        f"row {record_number} has {len(row)} fields; "
                        f"expected {len(header)}"
                    )
                rows.append((record_number, row))
            return header, rows
    except CsvInsightsError:
        raise
    except csv.Error as exc:
        raise CsvInsightsError(f"malformed CSV: {exc}") from exc
    except UnicodeError as exc:
        raise CsvInsightsError(f"input is not valid UTF-8: {exc}") from exc
    except OSError as exc:
        raise CsvInsightsError(f"cannot read {path!r}: {exc}") from exc


def parse_filters(raw_filters: list[str], header: list[str]) -> list[tuple[int, str]]:
    filters: list[tuple[int, str]] = []
    for expression in raw_filters:
        if "=" not in expression:
            raise CsvInsightsError(
                f"malformed filter {expression!r}; expected COLUMN=VALUE"
            )
        column, value = expression.split("=", 1)
        if not column:
            raise CsvInsightsError(
                f"malformed filter {expression!r}; column must be non-empty"
            )
        filters.append((column_index(column, header), value))
    return filters


def column_index(column: str, header: list[str]) -> int:
    try:
        return header.index(column)
    except ValueError:
        raise CsvInsightsError(f"unknown column {column!r}") from None


def decimal_text(value: Decimal) -> str:
    if value == 0:
        return "0"
    text = format(value, "f")
    if "." in text:
        text = text.rstrip("0").rstrip(".")
    return text


def aggregate(
    rows: list[tuple[int, list[str]]],
    header: list[str],
    group_column: str,
    sum_columns: list[str],
    avg_columns: list[str],
) -> tuple[list[str], list[list[str]]]:
    group_index = column_index(group_column, header)
    sum_specs = [(name, column_index(name, header)) for name in sum_columns]
    avg_specs = [(name, column_index(name, header)) for name in avg_columns]
    numeric_indices = dict(sum_specs + avg_specs)

    groups: dict[str, dict[str, list[Decimal]]] = {}
    for record_number, row in rows:
        values: dict[str, Decimal] = {}
        for name, index in numeric_indices.items():
            cell = row[index]
            if not cell:
                raise CsvInsightsError(
                    f"row {record_number}, column {name!r}: blank numeric value"
                )
            try:
                value = Decimal(cell)
            except InvalidOperation:
                raise CsvInsightsError(
                    f"row {record_number}, column {name!r}: "
                    f"invalid numeric value {cell!r}"
                ) from None
            if not value.is_finite():
                raise CsvInsightsError(
                    f"row {record_number}, column {name!r}: "
                    f"invalid numeric value {cell!r}"
                )
            values[name] = value

        group = groups.setdefault(row[group_index], {})
        for name, value in values.items():
            group.setdefault(name, []).append(value)

    output_header = [group_column]
    output_header.extend(f"sum_{name}" for name in sum_columns)
    output_header.extend(f"avg_{name}" for name in avg_columns)
    output_rows: list[list[str]] = []
    for group_value in sorted(groups):
        group = groups[group_value]
        result = [group_value]
        result.extend(decimal_text(sum(group[name], Decimal(0))) for name in sum_columns)
        result.extend(
            decimal_text(sum(group[name], Decimal(0)) / len(group[name]))
            for name in avg_columns
        )
        output_rows.append(result)
    return output_header, output_rows


def write_output(
    output: TextIO, output_format: str, header: list[str], rows: list[list[str]]
) -> None:
    if output_format == "csv":
        writer = csv.writer(output, lineterminator="\r\n")
        writer.writerow(header)
        writer.writerows(rows)
        return

    objects = [OrderedDict(zip(header, row)) for row in rows]
    json.dump(objects, output, ensure_ascii=False, indent=2)
    output.write("\n")


def run(args: argparse.Namespace) -> None:
    header, numbered_rows = read_csv(args.input)
    filters = parse_filters(args.where, header)
    filtered = [
        (number, row)
        for number, row in numbered_rows
        if all(row[index] == expected for index, expected in filters)
    ]

    if args.group_by:
        output_header, output_rows = aggregate(
            filtered,
            header,
            args.group_by,
            args.sum_columns,
            args.avg_columns,
        )
    else:
        output_header = header
        output_rows = [row for _, row in filtered]
    write_output(sys.stdout, args.output, output_header, output_rows)


def main(argv: Sequence[str] | None = None) -> int:
    args = parse_args(argv)
    try:
        run(args)
    except CsvInsightsError as exc:
        fail(str(exc))
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
